export const getSubmitShopPricingUrl = () => {
  return `/api/shop-pricing/submit`;
};

export const submitShopPricing = async (
  pricingSubmission: PricingSubmission,
  options?: RequestInit,
): Promise<SubmitResult> => {
  return customFetch<SubmitResult>(getSubmitShopPricingUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(pricingSubmission),
  });
};

export const getSubmitShopPricingMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof submitShopPricing>>,
    TError,
    { data: BodyType<PricingSubmission> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof submitShopPricing>>,
  TError,
  { data: BodyType<PricingSubmission> },
  TContext
> => {
  const mutationKey = ["submitShopPricing"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof submitShopPricing>>,
    { data: BodyType<PricingSubmission> }
  > = (props) => {
    const { data } = props ?? {};

    return submitShopPricing(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type SubmitShopPricingMutationResult = NonNullable<
  Awaited<ReturnType<typeof submitShopPricing>>
>;
